def execute_agent_action(tool_registry, action_request):
    tool_name = action_request.get('name')
    args = action_request.get('args', {})
    if tool_name not in tool_registry:
        return {'status': 'error', 'result': 'Unknown tool'}
    try:
        output = tool_registry[tool_name](**args)
        return {'status': 'success', 'result': output}
    except Exception as e:
        return {'status': 'error', 'result': str(e)}

registry = {'add': lambda a, b: a + b}
print(execute_agent_action(registry, {'name': 'add', 'args': {'a': 5, 'b': 7}}))
print(execute_agent_action(registry, {'name': 'subtract', 'args': {'a': 5, 'b': 2}}))
